    fun code(groups: List<Int>): String = groups.take(256)
        .filter { it in groupCodes.indices && it in validGroups }
        .map { groupCodes[it] }
        .joinToString("")

    fun group(code: Char): Int? = groupCodes.indices.firstOrNull { it in validGroups && groupCodes[it] == code }
